\set ON_ERROR_STOP on
insert into users values('00000000-0000-4000-8000-000000000008'),('00000000-0000-4000-8000-000000000009');
insert into tenant_memberships values('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000008','active','member'),('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000009','active','member');
do $$ declare tenant uuid:='10000000-0000-4000-8000-000000000001';owner uuid:='00000000-0000-4000-8000-000000000001';target uuid:='00000000-0000-4000-8000-000000000008';manager uuid:='00000000-0000-4000-8000-000000000009';foreign_actor uuid:='00000000-0000-4000-8000-000000000004';result jsonb;version1 uuid;version2 uuid;role_id uuid;assignment_id uuid;data jsonb;
begin
 if public.assessment_has_capability(tenant,owner,'unknown.permission') then raise exception 'Owner gained unknown permission';end if;
 begin perform assessment_staff_read(foreign_actor,tenant,'members');raise exception 'Foreign actor read institution staff';exception when insufficient_privilege then null;end;
 begin perform assessment_staff_command(owner,tenant,'staff-proctor-bypass','capability.grant',jsonb_build_object('user_id',target,'capability','proctor.manage','expected_revision',0,'reason','Bypass'));raise exception 'Assessment staff command granted Proctor authority';exception when check_violation then null;end;
 data:=jsonb_build_object('user_id',target,'capability','grades.mark','expected_revision',0,'reason','Marking responsibility');result:=assessment_staff_command(owner,tenant,'staff-grant-first','capability.grant',data);
 if assessment_staff_command(owner,tenant,'staff-grant-first','capability.grant',data)<>result or not assessment_has_capability(tenant,target,'grades.mark') then raise exception 'Permission grant replay failed';end if;
 if (select count(*) from assessment_audit_events where action='staff.capability.grant' and target_id=target)<>1 then raise exception 'Grant replay duplicated audit';end if;
 begin perform assessment_staff_command(owner,tenant,'staff-grant-stale','capability.grant',data);raise exception 'Stale grant revision overwrote permission';exception when unique_violation then null;end;
 perform assessment_staff_command(owner,tenant,'staff-grant-revoke','capability.revoke',jsonb_build_object('user_id',target,'capability','grades.mark','expected_revision',1,'reason','Withdraw responsibility'));if assessment_has_capability(tenant,target,'grades.mark') then raise exception 'Revoked direct grant remained effective';end if;
 result:=assessment_staff_command(owner,tenant,'staff-role-create','role.create','{"title":"Question author","capabilities":["banks.read","items.write"],"reason":"Author role"}');version1:=(result->>'id')::uuid;role_id:=(result->>'role_id')::uuid;
 result:=assessment_staff_command(owner,tenant,'staff-role-assign','role.assign',jsonb_build_object('user_id',target,'role_version_id',version1,'expected_assignment_id',null,'reason','Assign author'));assignment_id:=(result->>'id')::uuid;
 if not assessment_has_capability(tenant,target,'items.write') or assessment_has_capability(tenant,target,'items.approve') then raise exception 'Role assignment authority incorrect';end if;
 result:=assessment_staff_command(owner,tenant,'staff-role-revise','role.revise',jsonb_build_object('role_id',role_id,'expected_version',1,'title','Author and reviewer','capabilities','["banks.read","items.write","items.approve"]'::jsonb,'reason','Updated role definition'));version2:=(result->>'id')::uuid;
 if assessment_has_capability(tenant,target,'items.approve') then raise exception 'Role revision silently upgraded existing assignment';end if;
 begin update assessment_staff_role_versions set capabilities=array['team.manage'] where id=version1;raise exception 'Role snapshot mutated';exception when check_violation then null;end;
 begin update assessment_staff_role_assignments set expires_at=clock_timestamp()+interval '1 year' where id=assignment_id;raise exception 'Assignment expiry mutated in place';exception when check_violation then null;end;
 begin perform assessment_staff_command(owner,tenant,'staff-role-stale-assign','role.assign',jsonb_build_object('user_id',target,'role_version_id',version2,'expected_assignment_id',null,'reason','Stale upgrade'));raise exception 'Stale assignment overwritten';exception when unique_violation then null;end;
 result:=assessment_staff_command(owner,tenant,'staff-role-upgrade','role.assign',jsonb_build_object('user_id',target,'role_version_id',version2,'expected_assignment_id',assignment_id,'reason','Explicit reviewed upgrade'));assignment_id:=(result->>'id')::uuid;if not assessment_has_capability(tenant,target,'items.approve') then raise exception 'Explicit assignment upgrade failed';end if;
 update tenant_memberships set status='inactive' where tenant_id=tenant and user_id=target;if assessment_has_capability(tenant,target,'items.write') then raise exception 'Inactive membership retained role rights';end if;
 begin perform assessment_staff_command(owner,tenant,'staff-inactive-grant','capability.grant',jsonb_build_object('user_id',target,'capability','grades.mark','expected_revision',2,'reason','Inactive'));raise exception 'Inactive member received new rights';exception when check_violation then null;end;
 perform assessment_staff_command(owner,tenant,'staff-inactive-revoke','role.revoke',jsonb_build_object('assignment_id',assignment_id,'expected_revision',1,'reason','Remove inactive assignment'));update tenant_memberships set status='active' where tenant_id=tenant and user_id=target;if assessment_has_capability(tenant,target,'items.write') then raise exception 'Reactivation restored withdrawn role';end if;
 perform assessment_staff_command(owner,tenant,'staff-manager-grant','capability.grant',jsonb_build_object('user_id',manager,'capability','team.manage','expected_revision',0,'expires_at',clock_timestamp()+interval '20 minutes','reason','Temporary staff manager'));
 perform assessment_staff_command(owner,tenant,'staff-manager-authority','capability.grant',jsonb_build_object('user_id',manager,'capability','banks.read','expected_revision',0,'expires_at',clock_timestamp()+interval '10 minutes','reason','Manager reading authority'));
 begin perform assessment_staff_command(manager,tenant,'staff-self-escalation','capability.grant',jsonb_build_object('user_id',manager,'capability','items.approve','expected_revision',0,'reason','Escalate'));raise exception 'Manager modified own authority';exception when insufficient_privilege then null;end;
 begin perform assessment_staff_command(manager,tenant,'staff-excess-authority','capability.grant',jsonb_build_object('user_id',target,'capability','items.approve','expected_revision',0,'reason','Excess'));raise exception 'Manager delegated a permission not held';exception when insufficient_privilege then null;end;
 begin perform assessment_staff_command(manager,tenant,'staff-delegate-management','capability.grant',jsonb_build_object('user_id',target,'capability','team.manage','expected_revision',0,'reason','Management bypass'));raise exception 'Manager delegated management itself';exception when insufficient_privilege then null;end;
 begin perform assessment_staff_command(manager,tenant,'staff-permanent-bypass','capability.grant',jsonb_build_object('user_id',target,'capability','banks.read','expected_revision',0,'reason','Outlive manager'));raise exception 'Temporary manager granted permanent rights';exception when check_violation then null;end;
 perform assessment_staff_command(manager,tenant,'staff-bounded-delegation','capability.grant',jsonb_build_object('user_id',target,'capability','banks.read','expected_revision',0,'expires_at',clock_timestamp()+interval '5 minutes','reason','Bounded delegation'));
 if not assessment_has_capability(tenant,target,'banks.read') then raise exception 'Valid bounded delegation rejected';end if;
 update assessment_capability_grants set expires_at=clock_timestamp()-interval '1 second' where tenant_id=tenant and user_id=target and capability='banks.read';if assessment_has_capability(tenant,target,'banks.read') then raise exception 'Expired direct grant remained effective';end if;
 begin perform assessment_staff_command(owner,tenant,'staff-org-role-change','capability.grant',jsonb_build_object('user_id','00000000-0000-4000-8000-000000000002','capability','grades.mark','expected_revision',0,'reason','Inherited'));raise exception 'Inherited organization rights changed through service grants';exception when check_violation then null;end;
 if jsonb_array_length(assessment_staff_read(owner,tenant,'roles'))<>2 then raise exception 'Role versions missing';end if;
 if (assessment_grading_read(owner,tenant,'access')->>'can_manage_team')::boolean is not true then raise exception 'Staff navigation projection missing';end if;
end; $$;
set role authenticated;
do $$ begin begin perform * from assessment_staff_role_assignments;raise exception 'Raw staff assignments exposed';exception when insufficient_privilege then null;end;begin perform assessment_staff_command('00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','raw-staff-bypass','role.create','{}');raise exception 'Authenticated actor forged staff command';exception when insufficient_privilege then null;end;end; $$;
reset role;
